  $('rCone').textContent = fmtInt(s.cones);
  $('rSph').textContent = fmtInt(s.spheres);
  $('rTor').textContent = fmtInt(s.tori);
  $('rEdges').textContent = fmtInt(s.edges) + ' / ' + fmtInt(s.verts);
